import { useTranslation } from 'react-i18next';
import { formatUZS } from '../data/mock';
import { useShop } from '../lib/store';
import { Ms } from './Ms';

export const CatalogProductCard = ({ product }) => {
  const { t } = useTranslation();
  const { addToCart, cart, favorites, setQty, toggleFavorite } = useShop();
  const inCart = cart.find((item) => item.productId === product.id);
  const isFav = favorites.includes(product.id);

  return (
    <div className="group relative flex flex-col justify-between rounded-xl bg-surface-container-lowest p-3 shadow-sm transition-all hover:shadow-md">
      <button
        className={`absolute right-4 top-4 z-10 flex h-8 w-8 items-center justify-center rounded-full bg-surface-container-lowest/90 shadow-xs backdrop-blur transition-colors ${
          isFav ? 'text-tertiary' : 'text-outline hover:text-tertiary'
        }`}
        onClick={() => toggleFavorite(product.id)}
        title={isFav ? t('removeFromFavorites') : t('addToFavorites')}
        type="button"
      >
        <Ms className={isFav ? 'text-tertiary' : ''} filled={isFav} name="favorite" size={18} />
      </button>
      <div>
        {/* Image + badges */}
        <div className="relative mb-3 flex aspect-square w-full items-center justify-center overflow-hidden rounded-lg bg-surface-container-low p-3">
          {product.badges && (
            <div className="absolute left-2 top-2 z-10 flex flex-col gap-1">
              {product.badges.map((badge) =>
                badge.express ? (
                  <span key={badge.text} className="flex items-center gap-0.5 rounded-md bg-primary px-1.5 py-0.5 font-label-sm text-[10px] font-bold text-on-primary">
                    <Ms name="bolt" size={10} /> {badge.text}
                  </span>
                ) : (
                  <span
                    key={badge.text}
                    className={`rounded-md px-2 py-0.5 font-label-sm text-label-sm font-extrabold ${
                      badge.tone === 'secondary'
                        ? 'bg-secondary-container text-on-secondary-fixed'
                        : badge.tone === 'primary'
                          ? 'bg-primary-container text-on-primary-container'
                          : 'bg-tertiary text-on-tertiary'
                    }`}
                  >
                    {badge.text}
                  </span>
                ),
              )}
            </div>
          )}
          {product.img ? (
            <img alt={product.name} className="h-full w-full object-contain transition-transform duration-300 group-hover:scale-105" src={product.img} />
          ) : (
            <span className="text-6xl transition-transform duration-300 group-hover:scale-105">{product.emoji}</span>
          )}
        </div>
        {/* Details */}
        <div className="space-y-1">
          <div className="flex items-center gap-1.5 font-label-sm text-label-sm text-on-surface-variant">
            <span className="flex items-center font-bold text-secondary">
              <Ms className="text-secondary" filled name="star" size={14} />
              {product.rating}
            </span>
            <span>({product.reviews})</span>
            <span>•</span>
            <span>{product.unit}</span>
          </div>
          <h3 className="line-clamp-2 font-headline-sm text-headline-sm font-bold text-on-surface transition-colors group-hover:text-primary">{product.name}</h3>
          <span className="block font-body-sm text-body-sm text-outline">{product.origin}</span>
        </div>
      </div>
      {/* Price + action */}
      <div className="mt-4 pt-2">
        <div className="mb-2.5 flex flex-col">
          {product.oldPrice && <span className="leading-tight font-body-sm text-body-sm text-outline line-through">{formatUZS(product.oldPrice)}</span>}
          <span className={`font-price-lg text-price-lg font-extrabold leading-none ${product.oldPrice ? 'text-tertiary' : 'text-on-surface'}`}>
            {formatUZS(product.price)}
          </span>
        </div>
        {inCart ? (
          <div className="flex w-full items-center justify-between rounded-xl bg-primary/10 p-1">
            <button
              className="flex h-8 w-8 items-center justify-center rounded-lg bg-surface-container-lowest text-primary shadow-xs transition-colors hover:bg-primary hover:text-on-primary"
              onClick={() => setQty(product.id, inCart.qty - 1)}
              type="button"
            >
              <Ms name="remove" size={18} />
            </button>
            <span className="font-label-md text-label-md font-extrabold text-primary">
              {inCart.qty} {t('item')}
            </span>
            <button
              className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary text-on-primary shadow-xs transition-colors hover:bg-primary-container"
              onClick={() => setQty(product.id, inCart.qty + 1)}
              type="button"
            >
              <Ms name="add" size={18} />
            </button>
          </div>
        ) : (
          <button
            className="flex w-full items-center justify-center gap-1.5 rounded-xl bg-primary px-3 py-2.5 font-label-md text-label-md font-bold text-on-primary shadow-xs transition-all hover:bg-primary-container active:scale-95"
            onClick={() => addToCart(product.id)}
            type="button"
          >
            <Ms name="add_shopping_cart" size={18} />
            <span>{t('addToCart')}</span>
          </button>
        )}
      </div>
    </div>
  );
};
